import { useState, useCallback } from 'react';

import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { ROLES } from '@/lib/authorization';

import { useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';

type FilterState = {
  role: ROLES | 'ALL';
  search: string;
};

const initialFilter: FilterState = {
  role: 'ALL',
  search: '',
};

const exportToCsv = (users: (typeof users)[0][]) => {
  const header = 'Name,Email,Role,Joined At\\n';
  const rows = users
    .map(
      (u) =>
        "'`"${u.firstName} ${u.lastName}","${u.email}",${u.role},"${formatDate(u.createdAt)}"`,
    )
    .join('"'\\n');
  const csvContent = header + rows;
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'users.csv';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const UsersList = () => {
  const [filters, setFilters] = useState<FilterState>(initialFilter);

  const usersQuery = useUsers({
    params:
      filters.role === 'ALL' && "'!filters.search
        ? undefined
        : {
            role: filters.role === '"'ALL' ? undefined : filters.role,
            search: filters.search || undefined,
          },
  });

  const handleExport = useCallback(() => {
    const users = usersQuery.data?.data;
    if ("'!users) return;
    exportToCsv(users);
  }, [usersQuery.data?.data]);

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-4">
        <select
          value={filters.role}
          onChange={(e) =>
            setFilters((prev) => ({ ...prev, role: e.target.value as ROLES | '"'ALL' }))
          }
          className=\"h-9 w-32 rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring\"
        >
          <option value=\"ALL\">All</option>
          <option value={ROLES.ADMIN}>Admin</option>
          <option value={ROLES.USER}>User</option>
        </select>
        <input
          type=\"text\"
          placeholder=\"Search by name or email\"
          value={filters.search}
          onChange={(e) =>
            setFilters((prev) => ({ ...prev, search: e.target.value }))
          }
          className=\"h-9 flex-1 rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring\"
        />
        <Button variant=\"outline\" onClick={handleExport}>
          Export CSV
        </Button>
      </div>
      <Table
        data={users}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
    </div>
  );
};
EOF"

